const data={study:{title:'Учёба',lead:'Материалы и ресурсы для вашего направления.',cards:[['Конспекты и материалы','Подборки по IT, экономике, дизайну и другим направлениям.'],['Онлайн-курсы','Бесплатные курсы и программы для развития навыков.'],['Репетиторы','Найдите помощь по предмету или подготовке к экзамену.']]},jobs:{title:'Работа и стажировки',lead:'Первый опыт, гибкая занятость и актуальные вакансии.',cards:[['Стажировки','Подборка позиций для студентов и выпускников.'],['IT-вакансии','Предложения компаний Astana Hub.'],['Работа на Enbek.kz','Национальная биржа труда.']]},housing:{title:'Жильё',lead:'Комнаты, соседи, общежития и аренда.',cards:[['Комнаты в аренду','Живые объявления на Krisha.kz.'],['Поиск соседа','Находите тех, с кем удобно делить жильё.'],['Общежития','Условия и контакты приёмных комиссий.']]},events:{title:'Мероприятия',lead:'Хакатоны, олимпиады, конференции и встречи.',cards:[['События Astana Hub','Технологические события по Казахстану.'],['Конкурсы и хакатоны','Соберите команду и подайте заявку.'],['Университетские события','Анонсы от студенческих сообществ.']]},grants:{title:'Гранты и стипендии',lead:'Возможности финансирования образования и обмена.',cards:[['Государственные гранты','Информация от МНВО РК.'],['Болашак','Условия и сроки приёма документов.'],['Erasmus+','Обмен и стажировки через международный офис вуза.']]},market:{title:'Обмен',lead:'Книги, техника и учебные вещи от студентов.',cards:[['Книги','Продайте или найдите учебники.'],['Техника','Ноутбуки, калькуляторы и аксессуары.'],['Учебные вещи','Всё нужное для учёбы в одном месте.']]}};
const type=document.body.dataset.page;const item=data[type];document.querySelector('#pageTitle').textContent=item.title;document.querySelector('#pageLead').textContent=item.lead;document.querySelector('#pageGrid').innerHTML=item.cards.map(c=>`<article class="page-card"><small>StudentHub KZ</small><h2>${c[0]}</h2><p>${c[1]}</p><a href="index.html#feed">Смотреть →</a></article>`).join('');
